#include <time.h>
#include <stdio.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>

// Function to demonstrate signal handling (optional, but shows context for EINTR)
void signal_handler(int signum) {
    printf("\n--- Caught signal %d. Interrupting sleep. ---\n", signum);
}

#define TARGET_DURATION_S 3

int main() {
    struct timespec duration;
    struct timespec remaining;
    int result;

    // Set up a signal handler so we can test EINTR interruption
    signal(SIGINT, signal_handler);

    // Initial requested sleep time: 3.25 seconds
    duration.tv_sec = TARGET_DURATION_S;
    duration.tv_nsec = 250000000; 

    printf("Starting nanosleep for %ld seconds and %ld nanoseconds.\n(Try pressing Ctrl+C within the first 3 seconds)\n",
           duration.tv_sec, duration.tv_nsec);

    // Loop to handle potential interruptions (EINTR) and resume sleep
    do {
        result = nanosleep(&duration, &remaining);

        if (result == 0) {
            printf("Sleep successfully completed.\n");
            break; // Exit loop on success
        }

        // Check specifically for interruption
        if (result == -1 && errno == EINTR) {
            printf("Sleep interrupted. Remaining time: %ld s, %ld ns. Resuming...\n",
                   remaining.tv_sec, remaining.tv_nsec);
            // Copy the remaining time back to duration for the next iteration
            duration = remaining;
        } else if (result == -1) {
            perror("nanosleep error");
            return 1;
        }
    } while (result == -1 && errno == EINTR);

    return 0;
}
